-- Cooperativa Valle Verde (datos simulados) - Proyecto: alerta temprana de mora
-- Fecha de corte de los datos: 2026-10-31
IF DB_ID('ValleVerde') IS NULL CREATE DATABASE ValleVerde;
GO
USE ValleVerde;
GO
IF OBJECT_ID('cuotas') IS NOT NULL DROP TABLE cuotas;
IF OBJECT_ID('creditos') IS NOT NULL DROP TABLE creditos;
IF OBJECT_ID('clientes') IS NOT NULL DROP TABLE clientes;
GO
CREATE TABLE clientes (
  id_cliente INT PRIMARY KEY, nombre NVARCHAR(100) NOT NULL, departamento NVARCHAR(50),
  ocupacion NVARCHAR(50), ingreso_mensual DECIMAL(12,2), fecha_registro DATE);
CREATE TABLE creditos (
  id_credito INT PRIMARY KEY, id_cliente INT NOT NULL REFERENCES clientes(id_cliente),
  producto NVARCHAR(40), monto DECIMAL(12,2), plazo_meses INT, tasa_anual DECIMAL(5,2),
  fecha_desembolso DATE, cuota_mensual DECIMAL(12,2));
CREATE TABLE cuotas (
  id_cuota INT PRIMARY KEY, id_credito INT NOT NULL REFERENCES creditos(id_credito),
  numero_cuota INT, fecha_vencimiento DATE, monto_cuota DECIMAL(12,2), fecha_pago DATE NULL);
GO
